v16_patch_code="\n# V16 resilience + restart-safe near-term conversation memory.\n_src_or_model=\"OPENROUTER_MODEL=os.environ.get('OPENROUTER_MODEL','nvidia/nemotron-3-ultra-550b-a55b:free')\"\n_src_or_model_new=_src_or_model+\"\\nMISTRAL_API_KEY=os.environ.get('MISTRAL_API_KEY','').strip()\\nMISTRAL_MODEL=os.environ.get('MISTRAL_MODEL','mistral-small-latest').strip() or 'mistral-small-latest'\"\nif _src_or_model not in src: raise RuntimeError('V16 provider env marker missing')\nsrc=src.replace(_src_or_model,_src_or_model_new,1)\n\n_provider_helpers=r\"\"\"\n_provider_down_until={}\n\ndef _provider_blocked(name):\n    return float(_provider_down_until.get(name,0) or 0)>time.time()\n\ndef _provider_fail(name,err):\n    s=str(err).lower()\n    if 'free-models-per-day' in s:\n        cooldown=21600\n    elif '429' in s or 'rate limit' in s or 'tokens per day' in s:\n        cooldown=3600\n    elif 'http 5' in s or 'timed out' in s or 'timeout' in s:\n        cooldown=120\n    else:\n        cooldown=30\n    _provider_down_until[name]=max(float(_provider_down_until.get(name,0) or 0),time.time()+cooldown)\n    print('PROVIDER_CIRCUIT_OPEN',json.dumps({'provider':name,'cooldown_s':cooldown,'error':cleanerr(err)},ensure_ascii=False),flush=True)\n\ndef _provider_success(name):\n    _provider_down_until.pop(name,None)\n\ndef mistral_chat(messages,max_tokens=3000,temperature=0.35):\n    if not MISTRAL_API_KEY: raise RuntimeError('MISTRAL_API_KEY missing')\n    payload={'model':MISTRAL_MODEL,'messages':messages,'max_tokens':max_tokens,'temperature':temperature}\n    j=http_json('https://api.mistral.ai/v1/chat/completions',payload,MISTRAL_API_KEY,180)\n    ch=j.get('choices') or []\n    if not ch: raise RuntimeError('Mistral returned no choices')\n    out=((ch[0].get('message') or {}).get('content') or '').strip()\n    if not out: raise RuntimeError('Mistral returned empty content')\n    state['last_reserve_provider']='mistral:'+MISTRAL_MODEL\n    print('AI_RESERVE_PROVIDER',json.dumps({'provider':'mistral','model':MISTRAL_MODEL},ensure_ascii=False),flush=True)\n    return out\n\n\"\"\"\n_groq_marker=\"def groq_chat(messages,model=None,reasoning='medium',max_tokens=2400):\\n\"\nif _groq_marker not in src: raise RuntimeError('V16 groq marker missing')\nsrc=src.replace(_groq_marker,_provider_helpers+_groq_marker,1)\n\n_old_groq_call=\"    j=http_json('https://api.groq.com/openai/v1/chat/completions',payload,GROQ_API_KEY)\\n\"\n_new_groq_call=\"\"\"    if _provider_blocked('groq'):\n        if MISTRAL_API_KEY: return mistral_chat(messages,max_tokens=max_tokens)\n        raise RuntimeError('Groq circuit open')\n    try:\n        j=http_json('https://api.groq.com/openai/v1/chat/completions',payload,GROQ_API_KEY)\n        _provider_success('groq')\n    except Exception as e:\n        _provider_fail('groq',e)\n        if MISTRAL_API_KEY:\n            try: return mistral_chat(messages,max_tokens=max_tokens)\n            except Exception as me:\n                print('MISTRAL_RESERVE_ERROR',cleanerr(me),flush=True)\n        raise\n\"\"\"\nif _old_groq_call not in src: raise RuntimeError('V16 groq call marker missing')\nsrc=src.replace(_old_groq_call,_new_groq_call,1)\n\n_old_or_block=\"\"\"    try:\n        j=http_json('https://openrouter.ai/api/v1/chat/completions',payload,OPENROUTER_API_KEY,180,extra)\n    except Exception as e:\n        # Some upstream free providers can reject optional reasoning controls. Retry once without them.\n        if 'HTTP 400' not in str(e):raise\n        payload.pop('reasoning',None)\n        j=http_json('https://openrouter.ai/api/v1/chat/completions',payload,OPENROUTER_API_KEY,180,extra)\n\"\"\"\n_new_or_block=\"\"\"    if _provider_blocked('openrouter'):\n        if MISTRAL_API_KEY: return mistral_chat(messages,max_tokens=max_tokens,temperature=temperature)\n        raise RuntimeError('OpenRouter circuit open')\n    try:\n        try:\n            j=http_json('https://openrouter.ai/api/v1/chat/completions',payload,OPENROUTER_API_KEY,180,extra)\n        except Exception as e:\n            # Some upstream free providers can reject optional reasoning controls. Retry once without them.\n            if 'HTTP 400' not in str(e): raise\n            payload.pop('reasoning',None)\n            j=http_json('https://openrouter.ai/api/v1/chat/completions',payload,OPENROUTER_API_KEY,180,extra)\n        _provider_success('openrouter')\n    except Exception as e:\n        _provider_fail('openrouter',e)\n        if MISTRAL_API_KEY:\n            try: return mistral_chat(messages,max_tokens=max_tokens,temperature=temperature)\n            except Exception as me:\n                print('MISTRAL_RESERVE_ERROR',cleanerr(me),flush=True)\n        raise\n\"\"\"\nif _old_or_block not in src: raise RuntimeError('V16 OpenRouter call marker missing')\nsrc=src.replace(_old_or_block,_new_or_block,1)\n\n_memory_code=r\"\"\"\ndef vk_recent_context(uid,current_text):\n    try:\n        r=vk('messages.getHistory',{'peer_id':int(uid),'count':18,'offset':0},20)\n        items=(r.get('items') or []) if isinstance(r,dict) else []\n        seq=[]\n        for m in reversed(items):\n            if not isinstance(m,dict): continue\n            txt=str(m.get('text') or '').strip()\n            if not txt: continue\n            low=txt.lower()\n            if low in ('/reset','/сброс'):\n                seq=[]\n                continue\n            if txt.startswith('/'):\n                continue\n            role='assistant' if int(m.get('out') or 0)==1 else 'user'\n            seq.append({'role':role,'content':txt[:5000]})\n        cur=str(current_text or '').strip()\n        if seq and seq[-1].get('role')=='user' and seq[-1].get('content','').strip()==cur:\n            seq.pop()\n        selected=[];used=0\n        for m in reversed(seq[-14:]):\n            content=str(m.get('content') or '')\n            room=14000-used\n            if room<=0: break\n            if len(content)>room: content=content[-room:]\n            selected.append({'role':m.get('role'),'content':content})\n            used+=len(content)\n            if len(selected)>=10: break\n        selected.reverse()\n        print('VK_HISTORY_RECOVERED',json.dumps({'uid':uid,'messages':len(selected),'chars':used},ensure_ascii=False),flush=True)\n        return selected\n    except Exception as e:\n        print('VK_HISTORY_RECOVERY_ERROR',cleanerr(e),flush=True)\n        return []\n\n\"\"\"\n_rr_marker=\"def routed_response(uid,text):\\n\"\nif _rr_marker not in src: raise RuntimeError('V16 routed_response marker missing')\nsrc=src.replace(_rr_marker,_memory_code+_rr_marker,1)\n\n_old_hist=\"    hist=history_by_uid.get(uid,[])[-10:]\\n\"\n_new_hist=\"    _local_hist=history_by_uid.get(uid,[])[-10:]\\n    _vk_hist=vk_recent_context(uid,text)\\n    hist=(_vk_hist if _vk_hist else _local_hist)[-10:]\\n\"\nif _old_hist not in src: raise RuntimeError('V16 history marker missing')\nsrc=src.replace(_old_hist,_new_hist,1)\n\n_start_probe_old=\"            else:state['openrouter_probe']='not_configured'\\n            return\\n\"\n_start_probe_new=\"\"\"            else:state['openrouter_probe']='not_configured'\n            if MISTRAL_API_KEY:\n                try:\n                    out=mistral_chat([{'role':'user','content':'Reply exactly OK.'}],64,0.0)\n                    state['mistral_probe']='ok' if out else 'empty'\n                    print('MISTRAL_PROBE_OK',flush=True)\n                except Exception as e:\n                    state['mistral_probe']='error'\n                    print('MISTRAL_PROBE_ERROR',cleanerr(e),flush=True)\n            else:\n                state['mistral_probe']='not_configured'\n            return\n\"\"\"\nif _start_probe_old not in src: raise RuntimeError('V16 startup probe marker missing')\nsrc=src.replace(_start_probe_old,_start_probe_new,1)\n"
inject="v16_patch_code="+repr(v16_patch_code)+"\nv9_patch_code += '\\n'+v16_patch_code\n"
